  type SupportTicketPriority,
  type SupportTicketStatus,
} from "./data";
import { catCN, Empty, HDSelect, MAvatar, MiniMenu, ownerLabel, PRIO_CN, Prio, relWhen, TicketStatus, TK_STATUS_CN, type HDOption, type MenuItem } from "./hd-ui";
import type { MCtx } from "./types";
import { type MTicketAssigneeCandidate } from "@/lib/admin/m-client";
import { useAdminAuth } from "@/lib/store/admin-auth";
import { shouldSendOnEnter } from "@/lib/keyboard-submit";

const TICKET_KEY = "I.support.tickets";
const SLA_KEY = "I.support.sla";
const REPLY_TEMPLATE_KEY = "I.session.replyTemplates";
const TICKET_ASSIGNEE_CANDIDATES_KEY = "I.support.ticketAssigneeCandidates";

type Scope = "active" | "resolved" | "archived" | "all";
const SCOPES: Array<[Scope, string]> = [
  ["active", "活跃"],
  ["resolved", "已解决"],
  ["archived", "已归档"],
  ["all", "全部"],
];
const ACTIVE_STATUSES: SupportTicketStatus[] = ["open", "in_progress", "pending_user"];
const STATUS_TRANSITIONS: Record<SupportTicketStatus, SupportTicketStatus[]> = {
  open: ["in_progress", "pending_user", "resolved", "closed"],
  in_progress: ["open", "pending_user", "resolved", "closed"],
  pending_user: ["open", "in_progress", "resolved", "closed"],
  resolved: ["open", "pending_user", "closed"],
  closed: ["open"],
};
const STATUS_ACTION_CN: Record<SupportTicketStatus, string> = {
  open: "重新打开",
  in_progress: "标记处理中",
  pending_user: "待用户补充",
  resolved: "标记已解决",
  closed: "关闭工单",
};
const CATEGORY_LIST: SupportTicketCategory[] = ["account", "withdrawal", "deposit", "hardware", "earnings", "genesis", "technical", "other"];
const PRIORITY_LIST: SupportTicketPriority[] = ["urgent", "high", "normal", "low"];

/* 工单分类 → 跨域处置直达链接(C/D/E 域)。按工单分类匹配一条直达路由,
 * 让坐席从工单详情一步跳到真正的处置流程,而不是只靠 toast + 手工导航。
 * href 接收 userId(已由工单详情保证为真实用户绑定)。 */
const CATEGORY_CROSS_LINKS: Array<{ category: SupportTicketCategory; href: (userId: number) => string; label: string; icon: "wallet" | "users" | "shield" | "box" | "coin" }> = [
  { category: "withdrawal", href: (uid) => `/users/search/${uid}#hub-withdrawal`, label: "去提现记录", icon: "wallet" },
  { category: "deposit", href: (uid) => `/users/search/${uid}#hub-deposit`, label: "去充值记录", icon: "wallet" },
  { category: "account", href: () => `/users/actions`, label: "去账户处置", icon: "users" },
  { category: "hardware", href: (uid) => `/users/search/${uid}#hub-devices`, label: "去设备明细", icon: "box" },
  { category: "earnings", href: (uid) => `/users/search/${uid}#hub-deposit`, label: "去收益明细", icon: "coin" },
];
function findCategoryCrossLink(category: SupportTicketCategory): typeof CATEGORY_CROSS_LINKS[number] | null {
  return CATEGORY_CROSS_LINKS.find((link) => link.category === category) ?? null;
}
const PAGE_SIZE_OPTIONS = ["8", "15", "30"];
const WHO_CN: Record<"user" | "agent" | "system" | "internal", string> = {
  user: "用户",
  agent: "坐席",
  system: "系统",
  internal: "内部",
};
type CreateTicketForm = {
  userId: string;
  category: SupportTicketCategory;
  priority: SupportTicketPriority;
  ownerAdminId: number;
  title: string;
  body: string;
};

type TicketOwnerOption = MTicketAssigneeCandidate & { label: string };

type PendingCreatedTicket = {
  subject: string;
  userId?: number;
  existingIds: string[];
};

function parseParamArray<T>(raw: string | undefined, fallback: T[]): T[] {
  if (!raw) return fallback;
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as T[]) : fallback;
  } catch {
    return fallback;
  }
}

function cloneTickets(rows: SupportTicket[]): SupportTicket[] {
  return rows.map((ticket) => ({ ...ticket, messages: ticket.messages.map((m) => ({ ...m })) }));
}

type LinkedConversation = { no: string; archived: boolean };

function linkedConversation(ticket: SupportTicket): LinkedConversation | null {
  for (const message of ticket.messages) {
    // M3→M2 转单会关闭源会话，因此返回链接必须直接进入“归档”；否则 q 搜索会落到空列表。
    const converted = message.body.match(/会话号[:：]\s*(CV-[^，。\s]+)/);
    if (converted?.[1]) return { no: converted[1], archived: true };
    // M2→M3 升级产生的是仍在处理的即时会话，继续进入默认活跃范围。
    const escalated = message.body.match(/即时会话\s+(CV-[^，。\s]+)/);
    if (escalated?.[1]) return { no: escalated[1], archived: false };
  }
  return null;
}

export function M2Tickets({ ctx }: { ctx: MCtx }) {
  const { pget, setParam, toast, openActionConfirm } = ctx;
  const authorities = useAdminAuth((state) => state.session?.authorities);
  const currentRole = useAdminAuth((state) => state.session?.role ?? state.role);
  const isSuperAdmin = currentRole === "super" || currentRole === "superadmin";
  const canWriteM2 = isSuperAdmin || Boolean(authorities?.includes("service_m2_write"));
  const ticketsAvailable = pget("I.support.ticketsAvailable") === "1";
  const ticketAssigneeCandidatesAvailable = pget("I.support.ticketAssigneeCandidatesAvailable") === "1";
  const tickets = useMemo(() => cloneTickets(parseParamArray<SupportTicket>(pget(TICKET_KEY), [])), [ctx.params, pget]);
  const replyTemplates = useMemo(
    () =>
      parseParamArray<SessionReplyTpl>(pget(REPLY_TEMPLATE_KEY), [])
        .filter((tpl) => tpl.type === "support" && tpl.status === "published")
        .map((tpl) => tpl.text),
    [ctx.params, pget],
  );
  const slaRows = useMemo(() => parseParamArray<SupportSla>(pget(SLA_KEY), []), [ctx.params, pget]);
  const ticketAssigneeCandidates = useMemo(
    () => parseParamArray<MTicketAssigneeCandidate>(pget(TICKET_ASSIGNEE_CANDIDATES_KEY), []),
    [ctx.params, pget],
  );
  const ownerOptions = useMemo(() => {
    const nameCounts = new Map<string, number>();
    ticketAssigneeCandidates.forEach((candidate) => {
      nameCounts.set(candidate.name, (nameCounts.get(candidate.name) ?? 0) + 1);
    });
    return ticketAssigneeCandidates.map<TicketOwnerOption>((candidate) => ({
      ...candidate,
      label: (nameCounts.get(candidate.name) ?? 0) > 1
        ? `${candidate.name} · #${candidate.adminId}`
        : candidate.name,
    }));
  }, [ticketAssigneeCandidates]);
  const ticketCategoryOptions = useMemo(() => {
    const cats = new Set<SupportTicketCategory>(CATEGORY_LIST);
    slaRows.forEach((row) => cats.add(row.category));
    return Array.from(cats).map((value) => ({ value, label: catCN(value) }));
  }, [slaRows]);

  const [scope, setScope] = useState<Scope>("active");
  const [categoryFilter, setCategoryFilter] = useState<"all" | SupportTicketCategory>("all");
  const [statusFilter, setStatusFilter] = useState<"all" | SupportTicketStatus>("all");
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [showCreate, setShowCreate] = useState(false);
  const [replyBody, setReplyBody] = useState("");
  const [internalNoteBody, setInternalNoteBody] = useState("");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(8);
  const [writePending, setWritePending] = useState(false);
  const [pendingCreatedTicket, setPendingCreatedTicket] = useState<PendingCreatedTicket | null>(null);
  const writeInFlight = useRef(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const requestedScope = params.get("scope");
    const requestedStatus = params.get("status");
    if (requestedScope === "active" || requestedScope === "resolved" || requestedScope === "archived" || requestedScope === "all") {
      setScope(requestedScope);
    }
    if (requestedStatus && (["open", "in_progress", "pending_user", "resolved", "closed"] as string[]).includes(requestedStatus)) {
      setStatusFilter(requestedStatus as SupportTicketStatus);
    }
  }, []);

  const selected = tickets.find((t) => t.id === selectedId) ?? null;

  useEffect(() => {
    const pending = pendingCreatedTicket;
    if (!pending) return;
    const authoritative = tickets.find((ticket) =>
      ticket.subject === pending.subject
      && ticket.userId === pending.userId
      && !pending.existingIds.includes(ticket.id));
    if (!authoritative) return;
    setPendingCreatedTicket(null);
    setSelectedId(authoritative.id);
    setDrawerOpen(true);
  }, [pendingCreatedTicket, tickets]);

  const resolvedCount = tickets.filter((t) => !t.archived && (t.status === "resolved" || t.status === "closed")).length;
  const archivedCount = tickets.filter((t) => t.archived).length;

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return tickets
      .filter((t) => {
        if (scope === "all") return true;
        if (scope === "archived") return t.archived;
        if (scope === "resolved") return !t.archived && (t.status === "resolved" || t.status === "closed");
        return !t.archived && ACTIVE_STATUSES.includes(t.status);
      })
      .filter((t) => statusFilter === "all" || t.status === statusFilter)
      .filter((t) => categoryFilter === "all" || t.category === categoryFilter)
      .filter((t) => {
        if (!q) return true;
        // 用户编码必须可搜(2026-08-06 原型对比 M-2):会话页把运营指引到「用工单台按用户搜」,
        // 而这里原本不认 userId —— 指引的路走不通,等于死路标。
        return [t.id, t.subject, t.owner, catCN(t.category), t.userId ? String(t.userId) : ""]
          .some((text) => text.toLowerCase().includes(q));
      })
      .sort((a, b) => b.lastReplyAt - a.lastReplyAt);
  }, [tickets, scope, statusFilter, categoryFilter, query]);

  useEffect(() => {
    if (drawerOpen && selectedId && !filtered.some((ticket) => ticket.id === selectedId)) {
      setDrawerOpen(false);
    }
  }, [drawerOpen, filtered, selectedId]);

  // 本地 page state 渲染设计稿 tk-pager(数字 + data-list-pager 供运行时分页门计数)。
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const curPage = Math.min(page, pageCount);
  useEffect(() => {
    setPage(1);
  }, [scope, statusFilter, categoryFilter, query, pageSize]);
  const start = (curPage - 1) * pageSize;
  const paged = filtered.slice(start, start + pageSize);

  useEffect(() => {
    setReplyBody("");
    setInternalNoteBody("");
  }, [selectedId]);

  // Esc 关抽屉
  useEffect(() => {
    if (!drawerOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setDrawerOpen(false);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [drawerOpen]);

  const openTicket = (id: string) => {
    setSelectedId(id);
    setDrawerOpen(true);
  };

  const commitTicketWrite = async (write: () => Promise<boolean>, successMessage: string): Promise<boolean> => {
    if (writeInFlight.current) {
      toast("操作正在提交,请稍候");
      return false;
    }
    writeInFlight.current = true;
    setWritePending(true);
    try {
      const succeeded = await write();
      if (succeeded) toast(successMessage);
      return succeeded;
    } finally {
      writeInFlight.current = false;
      setWritePending(false);
    }
  };

  const updateTicket = async (id: string, updater: (t: SupportTicket) => SupportTicket, reason: string, action: string): Promise<boolean> => {
    const next = tickets.map((t) => (t.id === id ? updater(t) : t));
    return setParam(TICKET_KEY, JSON.stringify(next), { action, reason });
  };

  const createTicket = async (form: CreateTicketForm) => {
    if (!canWriteM2 || !ticketsAvailable || !ticketAssigneeCandidatesAvailable) return;
    const title = form.title.trim();
    const body = form.body.trim();
    const userId = form.userId.trim() ? Number(form.userId) : undefined;
    if (!title || !body) {
      toast("新建工单需要标题和问题描述");
      return;
    }
    if (userId !== undefined && (!Number.isSafeInteger(userId) || userId <= 0)) {
      toast("用户 ID 必须是正整数,也可以留空");
      return;
    }
    const selectedOwner = ownerOptions.find((candidate) => candidate.adminId === form.ownerAdminId);
    if (!selectedOwner) {
      toast("新建工单需要选择真实客服负责人");
      return;
    }
    const selectedSla = slaRows.find((item) => item.category === form.category);
    if (!selectedSla) {
      toast("该分类 SLA 权威规则不可用,请刷新后重试");
      return;
    }
    const now = Date.now();
    const row: SupportTicket = {
      id: `TK-${now}`,
      userId,
      userVerified: false,
      subject: title,
      category: form.category,
      status: "open",
      priority: form.priority,
      createdAt: now,
      updatedAt: now,
      lastReplyAt: now,
      unread: 1,
      ownerAdminId: selectedOwner.adminId,
      owner: selectedOwner.name,
      archived: false,
      version: 0,
      slaTarget: {
        ruleVersion: selectedSla.version,
        firstResponseMins: selectedSla.firstResponseMins,
        resolutionHours: selectedSla.resolutionHours,
        queue: selectedSla.queue,
        escalation: selectedSla.escalation,
        firstResponseDeadlineAt: now + selectedSla.firstResponseMins * 60_000,
        resolutionDeadlineAt: now + selectedSla.resolutionHours * 3_600_000,
        firstResponseOverdue: false,
        resolutionOverdue: false,
        evaluatedAt: now,
      },
      messages: [{ ts: now, author: "user", body }],
    };
    setPendingCreatedTicket({ subject: title, userId, existingIds: tickets.map((ticket) => ticket.id) });
    const succeeded = await commitTicketWrite(
      () => setParam(TICKET_KEY, JSON.stringify([row, ...tickets]), { action: "新建客服工单 · admin.support_ticket_created", reason: "客服人工新建工单并自动留档" }),
      `工单已创建并进入 ${selectedOwner.label} 队列`,
    );
    if (succeeded) {
      setShowCreate(false);
    } else {
      setPendingCreatedTicket(null);
    }
  };

  // 例行:回复(正文本身即留档)
  const sendReply = async (body: string) => {
    if (!selected || !canWriteM2 || !ticketsAvailable || selected.archived) return;
    if (!body.trim()) {
      toast("回复需要正文");
      return;
    }
    const now = Date.now();
    const succeeded = await commitTicketWrite(
      () => updateTicket(
        selected.id,
        (t) => ({
          ...t,
          status: "pending_user",
          updatedAt: now,
          lastReplyAt: now,
          unread: 0,
          messages: [...t.messages, { ts: now, author: "agent", agentName: t.owner === "Unassigned" ? "客服台" : t.owner, body: body.trim() }],
        }),
        "坐席回复(正文已留档)",
        `工单回复 ${selected.id} · admin.support_ticket_replied`,
      ),
      `${selected.id} 已回复并转待用户`,
    );
    if (succeeded) setReplyBody("");
  };

  // 例行:直接流转状态(状态菜单 + 关闭/重开)。closeOrReopen 保留关闭↔重开翻转。
  const setTicketStatusDirect = async (id: string, status: SupportTicketStatus) => {
    if (!canWriteM2 || !ticketsAvailable) return;
    const t = tickets.find((x) => x.id === id);
    if (!t || t.archived || t.status === status) return;
    const now = Date.now();
    await commitTicketWrite(
      () => updateTicket(id, (x) => ({ ...x, status, updatedAt: now }), `状态流转「${TK_STATUS_CN[status]}」(例行,自动留档)`, `工单状态流转 ${id} · admin.support_ticket_status`),
      `${id} → ${TK_STATUS_CN[status]}`,
    );
  };
  const closeOrReopen = async () => {
    if (!selected || !canWriteM2 || !ticketsAvailable || selected.archived) return;
    const now = Date.now();
    const nextStatus: SupportTicketStatus = selected.status === "closed" || selected.status === "resolved" ? "open" : "closed";
    await commitTicketWrite(
      () => updateTicket(
        selected.id,
        (t) => ({ ...t, status: nextStatus, updatedAt: now }),
        `坐席${nextStatus === "closed" ? "关闭" : "重开"}工单(例行,自动留档)`,
        `${nextStatus === "closed" ? "关闭" : "重开"}工单 ${selected.id} · admin.support_ticket_${nextStatus === "closed" ? "closed" : "reopened"}`,
      ),
      `${selected.id} 已${nextStatus === "closed" ? "关闭" : "重开"}`,
    );
  };

  // 例行:改优先级 / 转交 owner
  const setPriorityDirect = async (id: string, priority: SupportTicketPriority) => {
    if (!canWriteM2 || !ticketsAvailable) return;
    const now = Date.now();
    await commitTicketWrite(
      () => updateTicket(id, (t) => ({ ...t, priority, updatedAt: now }), `调整优先级「${PRIO_CN[priority]}」(例行,自动留档)`, `工单优先级 ${id} · admin.support_ticket_priority`),
      `${id} 优先级 → ${PRIO_CN[priority]}`,
    );
  };
  const setOwnerDirect = async (id: string, ownerAdminId: number) => {
    if (!canWriteM2 || !ticketsAvailable || !ticketAssigneeCandidatesAvailable) return;
    const selectedOwner = ownerOptions.find((candidate) => candidate.adminId === ownerAdminId);
    if (!selectedOwner) {
      toast("只能转交给当前可接单的客服坐席");
      return;
    }
    const now = Date.now();
    await commitTicketWrite(
      () => updateTicket(id, (t) => ({ ...t, ownerAdminId: selectedOwner.adminId, owner: selectedOwner.name, updatedAt: now }), `转交坐席「${selectedOwner.label}」(例行,自动留档)`, `工单转交 ${id} · admin.support_ticket_owner`),
      `${id} 已转交 ${selectedOwner.label}`,
    );
  };

  const setArchivedDirect = async (id: string, archived: boolean) => {
    if (!canWriteM2 || !ticketsAvailable) return;
    const ticket = tickets.find((item) => item.id === id);
    if (!ticket || Boolean(ticket.archived) === archived) return;
    if (archived && ticket.status !== "resolved" && ticket.status !== "closed") {
      toast("只有已解决或已关闭的工单可以归档");
      return;
    }
    const now = Date.now();
    await commitTicketWrite(
      () => updateTicket(
        id,
        (item) => ({ ...item, archived, archivedAt: archived ? now : undefined, updatedAt: now }),
        archived ? "已解决工单例行归档并自动留档" : "归档工单恢复到已解决队列并自动留档",
        `${archived ? "归档" : "恢复"}工单 ${id} · admin.support_ticket_${archived ? "archived" : "unarchived"}`,
      ),
      `${id} 已${archived ? "归档" : "恢复到已解决队列"}`,
    );
  };

  const addInternalNote = async (body: string) => {
    if (!selected || !canWriteM2 || !ticketsAvailable || selected.archived) return;
    const note = body.trim();
    if (!note) {
      toast("内部备注需要正文");
      return;
    }
    const succeeded = await commitTicketWrite(
      () => setParam("I.support.ticketInternalNote.__create", JSON.stringify({
        ticketNo: selected.id,
        body: note,
        expectedStatus: selected.status,
        expectedVersion: selected.version,
      }), {
        action: `工单内部备注 ${selected.id} · admin.support_ticket_internal_note`,
        reason: "客服内部协作备注自动留档",
        commandKey: `m2:ticket:${selected.id}:internal-note:${selected.version}:${note}`,
      }),
      `${selected.id} 内部备注已保存`,
    );
    if (succeeded) setInternalNoteBody("");
  };

  // 处置:升级为即时会话(不传 edit;真写对方真写键 I.session.convos + 工单 thread 留系统标注)
  const escalateToConversation = () => {
    if (!selected || !canWriteM2 || !ticketsAvailable || selected.archived) return;
    const ticket = selected;
    if (!ticket.userId || ticket.userId <= 0 || !ticket.userVerified) {
      toast("该工单没有后端确认的真实用户,请先核对用户后再升级会话");
      return;
    }
    const assignedCandidate = ticketAssigneeCandidates.find((candidate) => ticket.ownerAdminId === candidate.adminId);
    if (!assignedCandidate) {
      toast("当前负责人不在可接单客服名册,请先转交后再升级会话");
      return;
    }
    openActionConfirm({
      action: <>升级为即时会话 · {ticket.id}</>,
      detail: (
        <>
          把工单 <b>{ticket.subject}</b> 升级为即时会话,坐席 <b>{ticket.owner}</b> 在会话中心继续实时接待;系统会保留真实用户关联,并在本工单同步记录会话编号。仅迁移接待载体,资金放行仍回 D2。
        </>
      ),
      amplifies: false,
      run: async (reason: string) => {
        const succeeded = await commitTicketWrite(
          () => setParam("I.support.ticketEscalation.__create", JSON.stringify({
            ticketNo: ticket.id,
            ownerAgentId: String(assignedCandidate.adminId),
            ownerAgentName: assignedCandidate.name,
            expectedStatus: ticket.status,
            expectedVersion: ticket.version,
          }), {
            action: `工单升级为即时会话 ${ticket.id} · admin.conversation_from_ticket`,
            reason,
            commandKey: `m2:ticket:${ticket.id}:escalate:${ticket.version}`,
          }),
          `${ticket.id} 已升级为即时会话`,
        );
        if (succeeded) setDrawerOpen(false);
        return succeeded;
      },
    });
  };

  const categoryOptions: HDOption[] = [{ value: "all", label: "全部分类" }, ...ticketCategoryOptions];

  const threadMessages: ThreadMessage[] = (selected?.messages ?? []).map((m) => ({
    ts: m.ts,
    fromAgent: m.author === "agent",
    agentName: m.agentName,
    senderName: m.author === "internal"
      ? `内部备注 · ${m.agentName ?? "客服台"}`
      : m.author === "system"
        ? "系统"
        : m.author === "agent"
          ? m.agentName ?? "客服台"
          : "用户",
    system: m.author === "system" || m.author === "internal",
    role: m.author === "user" ? "user" : "support",
    body: m.body,
  }));

  return (
    <div className="tk-wrap m2-stage">
      <p className="dim" style={{ margin: "0 0 12px", fontSize: 13 }}>
        用户提的问题在这排队 · 点一行打开<b style={{ color: "var(--ink-2)", fontWeight: 500 }}>工单详情与处理</b>:回复 / 改状态 / 转交 / 关单 / 升级为即时会话。
      </p>
      {!ticketsAvailable && (
        <div className="itint" role="alert" style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 13 }}>工单数据暂时无法同步,当前不展示空队列,也不会开放写操作。</div>
          <div className="dim2" style={{ fontSize: 11.5, marginTop: 4 }}>请稍后刷新页面;若持续失败,联系平台管理员检查客服工单服务。</div>
        </div>
      )}
      {ticketsAvailable && !canWriteM2 && (
        <div className="itint" role="status" style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 13 }}>当前账号为只读模式。</div>
          <div className="dim2" style={{ fontSize: 11.5, marginTop: 4 }}>可以筛选和查看工单,回复、流转、归档及升级会话需要 M2 写权限。</div>
        </div>
      )}
      {ticketsAvailable && canWriteM2 && !ticketAssigneeCandidatesAvailable && (
        <div className="itint" role="alert" style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 13 }}>坐席候选数据暂时无法同步,当前不会开放新建或转交操作。</div>
          <div className="dim2" style={{ fontSize: 11.5, marginTop: 4 }}>这不是 M2 权限不足;请稍后刷新,持续失败时检查客服坐席目录服务。</div>
        </div>
      )}
      {ticketsAvailable && canWriteM2 && ticketAssigneeCandidatesAvailable && ownerOptions.length === 0 && (
        <div className="itint" role="alert" style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 13 }}>当前没有可接单的客服坐席。</div>
          <div className="dim2" style={{ fontSize: 11.5, marginTop: 4 }}>请先在 M1 启用具备客服服务类型且允许转交的坐席。</div>
        </div>
      )}
      <div className="tk-toolbar">
        <TabGroup<Scope>
          className="seg"
          label="工单范围筛选"
          value={scope}
          items={SCOPES.map(([k]) => k)}
          onSelect={setScope}
          itemClassName={(_k, selected) => (selected ? "on" : undefined)}
        >{(k) => (
          <>
            {k === "archived" && <Icon name="box" size={14} />}
            {SCOPES.find(([value]) => value === k)?.[1]}
            {k === "resolved" ? ` ${resolvedCount}` : k === "archived" ? ` ${archivedCount}` : ""}
          </>
        )}</TabGroup>
        <div style={{ width: 188 }}>
          <HDSelect value={categoryFilter} onChange={(v) => setCategoryFilter(v as "all" | SupportTicketCategory)} options={categoryOptions} />
        </div>
        <div style={{ width: 150 }}>
          <HDSelect
            value={statusFilter}
            onChange={(v) => setStatusFilter(v as "all" | SupportTicketStatus)}
            options={[{ value: "all", label: "全部状态" }, ...Object.entries(TK_STATUS_CN).map(([value, label]) => ({ value, label }))]}
          />
        </div>
        <div className="inp" style={{ flex: 1, maxWidth: 320 }}>
          <Icon name="search" size={15} />
          <input data-proof="support-ticket-search" aria-label="搜索工单主题、单号、负责人、分类或用户编码" placeholder="搜索主题 / 单号 / 负责人 / 分类 / 用户编码" value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
        {canWriteM2 && ticketsAvailable && ticketAssigneeCandidatesAvailable && ownerOptions.length > 0 && (
          <button type="button" data-proof="support-ticket-create" className="btn btn-pri btn-sm" disabled={writePending} onClick={() => setShowCreate(true)}>
            <Icon name="plus" size={16} />
            新建工单
          </button>
        )}
        <span className="mono dim2" style={{ marginLeft: "auto", fontSize: 12.5 }}>共 {filtered.length} 条</span>
      </div>

      <div className="tk-scroll">
        <table className="tk-table">
          <thead>
            <tr>
              <th style={{ width: "38%" }}>工单</th>
              <th style={{ width: 110 }}>分类</th>
              <th style={{ width: 86 }}>优先级</th>
              <th style={{ width: 120 }}>状态</th>
              <th style={{ width: 132 }}>负责人</th>
              <th style={{ width: 150 }}>最近回复</th>
              <th style={{ textAlign: "right" }}>操作</th>
            </tr>
          </thead>
          <tbody>
            {paged.map((t) => {
              const last = t.messages[t.messages.length - 1];
              const sel = drawerOpen && selected?.id === t.id;
              const done = t.status === "resolved" || t.status === "closed";
              return (
                <tr key={t.id} className={`tk-row${sel ? " sel" : ""}`} onClick={() => openTicket(t.id)}>
                  <td>
                    <div className="tk-subj">{t.subject}</div>
                    <div className="tk-id">{t.id}</div>
                  </td>
                  <td>
                    <span className="chip" style={{ border: "none" }}>{catCN(t.category)}</span>
                  </td>
                  <td>
                    <Prio p={t.priority} />
                  </td>
                  <td>
                    <TicketStatus status={t.status} />
                  </td>
                  <td>
                    <span className="agent">
                      <MAvatar name={t.owner} size="sm" />
                      <span className="nm" style={{ fontSize: 12.5 }}>{ownerLabel(t.owner)}</span>
                    </span>
                  </td>
                  <td>
                    <div className="mono" style={{ fontSize: 12, color: "var(--ink-2)" }}>{relWhen(t.lastReplyAt)}</div>
                    <div className="dim2" style={{ fontSize: 11 }}>{last ? WHO_CN[last.author] : "—"}回复</div>
                  </td>
                  <td onClick={(e) => e.stopPropagation()}>
                    <div className="tk-acts">
                      {canWriteM2 && ticketsAvailable && !t.archived && !done && (
                        <button type="button" className="tk-iact ok" title="标记已解决" onClick={() => setTicketStatusDirect(t.id, "resolved")}>
                          <Icon name="check" size={16} />
                        </button>
                      )}
                      {canWriteM2 && ticketsAvailable && t.archived ? (
                        <button type="button" className="tk-iact" title="恢复到已解决队列" onClick={() => setArchivedDirect(t.id, false)}>
                          <Icon name="arrow" size={16} />
                        </button>
                      ) : canWriteM2 && ticketsAvailable && done ? (
                        <>
                          <button type="button" className="tk-iact" title="归档" onClick={() => setArchivedDirect(t.id, true)}>
                            <Icon name="box" size={16} />
                          </button>
                          <button type="button" className="tk-iact" title="重新打开" onClick={() => setTicketStatusDirect(t.id, "open")}>
                            <Icon name="arrow" size={16} />
                          </button>
                        </>
                      ) : canWriteM2 && ticketsAvailable ? (
                        <button type="button" className="tk-iact" title="关闭" onClick={() => setTicketStatusDirect(t.id, "closed")}>
                          <Icon name="x" size={16} />
                        </button>
                      ) : null}
                      <button type="button" className="btn btn-sec btn-sm" title="打开处理" onClick={() => openTicket(t.id)}>
                        <Icon name="eye" size={16} />
                        处理
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {ticketsAvailable && !filtered.length && <Empty icon="search">没有匹配的工单;可以调整筛选条件{canWriteM2 && ticketAssigneeCandidatesAvailable && ownerOptions.length > 0 ? "或新建工单" : ""}</Empty>}
      </div>

      {filtered.length > 0 && (
        <div className="tk-pager" data-list-pager="true">
          <span className="dim2" style={{ fontSize: 12.5 }}>
            显示 {start + 1}–{Math.min(start + pageSize, filtered.length)} · 共 {filtered.length} 条
          </span>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginLeft: 14 }}>
            <span className="dim2" style={{ fontSize: 12.5 }}>每页</span>
            <div style={{ width: 78 }}>
              <HDSelect value={String(pageSize)} onChange={(v) => setPageSize(Number(v))} options={PAGE_SIZE_OPTIONS.map((n) => ({ value: n, label: n }))} />
            </div>
          </div>
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 6 }}>
            <button type="button" className="btn btn-sec btn-sm btn-icon" disabled={curPage <= 1} title="上一页" onClick={() => setPage(curPage - 1)}>
              <span style={{ display: "inline-flex", transform: "rotate(180deg)" }}>
                <Icon name="chevron" size={16} />
              </span>
            </button>
            {Array.from({ length: pageCount }, (_, i) => i + 1).map((p) => (
              <button key={p} type="button" className={`tk-pageno${p === curPage ? " on" : ""}`} onClick={() => setPage(p)}>
                {p}
              </button>
            ))}
            <button type="button" className="btn btn-sec btn-sm btn-icon" disabled={curPage >= pageCount} title="下一页" onClick={() => setPage(curPage + 1)}>
              <Icon name="chevron" size={16} />
            </button>
          </div>
        </div>
      )}

      {drawerOpen && selected && (
        <TicketDrawer
          ticket={selected}
          replyBody={replyBody}
          onReplyChange={setReplyBody}
          internalNoteBody={internalNoteBody}
          onInternalNoteChange={setInternalNoteBody}
          onInternalNote={addInternalNote}
          onClose={() => setDrawerOpen(false)}
          onSend={sendReply}
          onStatus={(s) => setTicketStatusDirect(selected.id, s)}
          onPriority={(p) => setPriorityDirect(selected.id, p)}
          onOwner={(o) => setOwnerDirect(selected.id, o)}
          onCloseReopen={closeOrReopen}
          onArchive={(archived) => setArchivedDirect(selected.id, archived)}
          onEscalate={escalateToConversation}
          thread={threadMessages}
          replyTemplates={replyTemplates}
          ownerOptions={ownerOptions}
          canWrite={canWriteM2 && ticketsAvailable && !writePending}
        />
      )}

      {showCreate && ticketAssigneeCandidatesAvailable && ownerOptions.length > 0 && (
        <CreateTicketModal
          categoryOptions={ticketCategoryOptions}
          ownerOptions={ownerOptions}
          submitting={writePending}
          onClose={() => setShowCreate(false)}
          onSave={createTicket}
        />
      )}
    </div>
  );
}

function TicketDrawer({
  ticket,
  replyBody,
  onReplyChange,
  internalNoteBody,
  onInternalNoteChange,
  onInternalNote,
  onClose,
  onSend,
  onStatus,
  onPriority,
  onOwner,
  onCloseReopen,
  onArchive,
  onEscalate,
  thread,
  replyTemplates,
  ownerOptions,
  canWrite,
}: {
  ticket: SupportTicket;
  replyBody: string;
  onReplyChange: (v: string) => void;
  internalNoteBody: string;
  onInternalNoteChange: (v: string) => void;
  onInternalNote: (body: string) => void;
  onClose: () => void;
  onSend: (body: string) => void;
  onStatus: (s: SupportTicketStatus) => void;
  onPriority: (p: SupportTicketPriority) => void;
  onOwner: (adminId: number) => void;
  onCloseReopen: () => void;
  onArchive: (archived: boolean) => void;
  onEscalate: () => void;
  thread: ThreadMessage[];
  replyTemplates: string[];
  ownerOptions: TicketOwnerOption[];
  canWrite: boolean;
}) {
  const isTerminal = ticket.status === "resolved" || ticket.status === "closed";
  const conversation = linkedConversation(ticket);
  const categoryCrossLink = findCategoryCrossLink(ticket.category);
  const statusItems: MenuItem[] = STATUS_TRANSITIONS[ticket.status].map((status) => ({ label: STATUS_ACTION_CN[status], onClick: () => onStatus(status) }));
  const priorityItems: MenuItem[] = PRIORITY_LIST.map((p) => ({ label: PRIO_CN[p], cur: ticket.priority === p, onClick: () => onPriority(p) }));
  const ownerItems: MenuItem[] = ownerOptions.map((candidate) => ({
    label: candidate.label,
    cur: ticket.ownerAdminId === candidate.adminId,
    onClick: () => onOwner(candidate.adminId),
  }));

  return (
    <>
      <div className="tk-drawer-back" onClick={onClose} />
      <div className="tk-drawer">
        <div style={{ padding: "15px 18px 14px", borderBottom: "1px solid var(--border)" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span className="idtag">{ticket.id}</span>
            <TicketStatus status={ticket.status} />
            <Prio p={ticket.priority} />
            <button type="button" className="btn btn-ghost btn-icon btn-sm" onClick={onClose} title="关闭 (Esc)" style={{ marginLeft: "auto" }}>
              <Icon name="x" size={16} />
            </button>
          </div>
          <h2 style={{ fontSize: 18, margin: "11px 0 0", fontWeight: 500 }}>{ticket.subject}</h2>
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginTop: 9, flexWrap: "wrap" }}>
            <span className="chip" style={{ border: "none" }}>{catCN(ticket.category)}</span>
            <span className="agent dim" style={{ fontSize: 12.5 }}>
              <MAvatar name={ticket.owner} size="sm" /> {ownerLabel(ticket.owner)}
            </span>
            <span className="dim2" style={{ fontSize: 12, display: "inline-flex", alignItems: "center", gap: 5 }}>
              <Icon name="clock" size={13} /> 更新 {relWhen(ticket.updatedAt)}
            </span>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 13, flexWrap: "wrap" }}>
            {canWrite && !ticket.archived && <MiniMenu label="状态" items={statusItems} />}
            {canWrite && !ticket.archived && !isTerminal && <MiniMenu label="优先级" items={priorityItems} />}
            {canWrite && !ticket.archived && ticket.status !== "closed" && ownerItems.length > 0 && <MiniMenu label="转交" icon="users" items={ownerItems} />}
            {ticket.userId && ticket.userVerified && <Link className="btn btn-sec btn-sm" href={`/users/search/${ticket.userId}#hub-payment-methods`}><Icon name="wallet" size={16} />用户支付方式</Link>}
            {ticket.userId && ticket.userVerified && categoryCrossLink && (
              <Link className="btn btn-cyan btn-sm" href={categoryCrossLink.href(ticket.userId)}>
                <Icon name={categoryCrossLink.icon} size={16} />{categoryCrossLink.label}
              </Link>
            )}
            <div style={{ flex: 1 }} />
            {conversation ? (
              <Link className="btn btn-cyan btn-sm" href={conversation.archived
                ? `/service/sessions?seg=archived&q=${encodeURIComponent(conversation.no)}`
                : `/service/sessions?q=${encodeURIComponent(conversation.no)}`}>
                <Icon name="arrow" size={16} />查看会话 {conversation.no}
              </Link>
            ) : canWrite && !ticket.archived && !isTerminal && (
              <button
                type="button"
                data-proof="support-ticket-escalate"
                className="btn btn-cyan btn-sm"
                onClick={onEscalate}
                disabled={!ticket.userId || ticket.userId <= 0 || !ticket.userVerified || !ownerOptions.some((candidate) => candidate.adminId === ticket.ownerAdminId)}
                title={!ownerOptions.some((candidate) => candidate.adminId === ticket.ownerAdminId)
                  ? "坐席候选数据不可用或当前负责人已不可接单,暂不能升级会话"
                  : ticket.userId && ticket.userId > 0 && ticket.userVerified
                    ? "升级为与该用户的即时会话"
                    : "该工单没有后端确认的真实用户,无法升级会话"}
              >
                <Icon name="arrow" size={16} />
                升级会话
              </button>
            )}
            {canWrite && !ticket.archived && (
              <button type="button" data-proof="support-ticket-close" className={`btn btn-sm ${isTerminal ? "btn-sec" : "btn-danger"}`} onClick={onCloseReopen}>
                <Icon name={isTerminal ? "arrow" : "x"} size={16} />
                {isTerminal ? "重新打开" : "关闭"}
              </button>
            )}
            {canWrite && !ticket.archived && isTerminal && (
              <button type="button" className="btn btn-sec btn-sm" onClick={() => onArchive(true)} title="移入可查询的已归档队列">
                <Icon name="box" size={16} />归档
              </button>
            )}
            {canWrite && ticket.archived && (
              <button type="button" className="btn btn-sec btn-sm" onClick={() => onArchive(false)} title="恢复到已解决队列">
                <Icon name="arrow" size={16} />恢复
              </button>
            )}
          </div>
          {ticket.userId && !ticket.userVerified && (
            <div className="callout warn" style={{ marginTop: 10, fontSize: 12 }}>
              用户 ID {ticket.userId} 未通过后端用户表校验；支付方式、跨域处置和升级会话均已关闭。
            </div>
          )}
          {ticket.slaTarget && (
            <div className="dim2" data-proof="support-ticket-sla" style={{ marginTop: 10, fontSize: 12 }}>
              SLA v{ticket.slaTarget.ruleVersion}：首响目标 {new Date(ticket.slaTarget.firstResponseDeadlineAt).toLocaleString()}
              {ticket.slaTarget.firstResponseOverdue ? " · 已逾期" : " · 未逾期"}
              {" · "}解决目标 {new Date(ticket.slaTarget.resolutionDeadlineAt).toLocaleString()}
              {ticket.slaTarget.resolutionOverdue ? " · 已逾期" : " · 未逾期"}
              {" · "}队列 {ticket.slaTarget.queue} · 升级 {ticket.slaTarget.escalation}
            </div>
          )}
        </div>

        <div className="ChatBody">
          <MessageThread messages={thread} relWhen={relWhen} />
        </div>

        {canWrite && !ticket.archived && (
          <div style={{ padding: "12px 18px", borderTop: "1px solid var(--border)", background: "var(--panel-2)" }}>
            <div className="dim2" style={{ fontSize: 11.5, marginBottom: 7 }}>
              内部备注仅客服可见，不会作为回复发送给用户
            </div>
            <textarea
              className="ta"
              data-proof="support-ticket-internal-note"
              rows={2}
              maxLength={2000}
              placeholder="记录内部核查、交接或 SLA 处置"
              value={internalNoteBody}
              onChange={(e) => onInternalNoteChange(e.target.value)}
            />
            <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 8 }}>
              <button
                type="button"
                data-proof="support-ticket-internal-note-save"
                className="btn btn-sec btn-sm"
                disabled={!internalNoteBody.trim()}
                onClick={() => onInternalNote(internalNoteBody)}
              >
                保存内部备注
              </button>
            </div>
          </div>
        )}

        {canWrite && ticket.status !== "closed" && !ticket.archived && (
          <div className="ChatComposer">
            <div style={{ display: "flex", gap: 7, marginBottom: 9, flexWrap: "wrap", alignItems: "center" }}>
              <span className="dim2" style={{ fontSize: 11.5, display: "inline-flex", alignItems: "center", gap: 4 }}>
                <Icon name="flame" size={13} />
                快捷回复
              </span>
              {replyTemplates.length === 0 && <span className="dim2" style={{ fontSize: 11.5 }}>暂无可用回复模板</span>}
              {replyTemplates.map((tpl, i) => (
                <button key={i} type="button" className="chip" title={tpl} onClick={() => onReplyChange(replyBody ? `${replyBody} ${tpl}` : tpl)}>
                  {tpl.slice(0, 14)}…
                </button>
              ))}
            </div>
            <textarea
              className="ta"
              data-proof="support-ticket-reply"
              aria-label={`回复工单 ${ticket.id}`}
              rows={3}
              placeholder={`回复 ${ticket.id} · Enter 发送 · Shift+Enter 换行`}
              value={replyBody}
              onChange={(e) => onReplyChange(e.target.value)}
              onKeyDown={(e) => {
                if (!shouldSendOnEnter(e)) return;
                e.preventDefault();
                onSend(replyBody);
              }}
            />
            <div style={{ display: "flex", alignItems: "center", marginTop: 9 }}>
              <span className="dim2" style={{ fontSize: 11.5 }}>例行回复直接执行并自动留档,无需理由 · 资金放行回 D2 / 账户处置回 C5 / 设备换货回 E5</span>
              <button type="button" data-proof="support-ticket-reply-save" className="btn btn-pri btn-sm" style={{ marginLeft: "auto" }} onClick={() => onSend(replyBody)}>
                <Icon name="arrow" size={16} />
                发送回复
              </button>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

function CreateTicketModal({
  categoryOptions,
  ownerOptions,
  submitting,
  onClose,
  onSave,
}: {
  categoryOptions: Array<{ value: SupportTicketCategory; label: string }>;
  ownerOptions: TicketOwnerOption[];
  submitting: boolean;
  onClose: () => void;
  onSave: (form: CreateTicketForm) => void;
}) {
  const firstOwnerAdminId = ownerOptions[0]?.adminId ?? 0;
  const [userId, setUserId] = useState("");
  const [category, setCategory] = useState<SupportTicketCategory>(categoryOptions[0]?.value ?? "account");
  const [priority, setPriority] = useState<SupportTicketPriority>("normal");
  const [ownerAdminId, setOwnerAdminId] = useState(firstOwnerAdminId);
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  return (
    <Modal
      title="新建客服工单"
      icon="doc"
      wide
      onClose={onClose}
      footer={
        <>
          <span className="dim2" style={{ fontSize: 11.5 }}>负责人来自客服坐席名册;新建会自动留档,无需填写理由</span>
          <span style={{ flex: 1 }} />
          <button type="button" className="btn btn-sec btn-sm" disabled={submitting} onClick={onClose}>取消</button>
          <button
            type="button"
            data-proof="support-ticket-create-save"
            className="btn btn-pri btn-sm"
            disabled={submitting || !ownerAdminId || !title.trim() || !body.trim()}
            onClick={() => onSave({ userId, category, priority, ownerAdminId, title, body })}
          >
            {submitting ? "保存中…" : "保存工单"}
          </button>
        </>
      }
    >
      <div className="grid g-3" style={{ gap: 12, marginBottom: 12 }}>
        <label className="field">
          <span className="bf-legend">分类</span>
          <select className="fld" value={category} onChange={(e) => setCategory(e.target.value as SupportTicketCategory)}>
            {categoryOptions.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}
          </select>
        </label>
        <label className="field">
          <span className="bf-legend">优先级</span>
          <select className="fld" value={priority} onChange={(e) => setPriority(e.target.value as SupportTicketPriority)}>
            {PRIORITY_LIST.map((item) => <option key={item} value={item}>{PRIO_CN[item]}</option>)}
          </select>
        </label>
        <label className="field">
          <span className="bf-legend">负责人</span>
          <select data-proof="support-ticket-create-owner" className="fld" value={String(ownerAdminId)} onChange={(e) => setOwnerAdminId(Number(e.target.value))}>
            {ownerOptions.map((item) => <option key={item.adminId} value={String(item.adminId)}>{item.label}</option>)}
          </select>
        </label>
      </div>
      <div style={{ display: "grid", gap: 12 }}>
        <label className="field">
          <span className="bf-legend">用户 ID(可选)</span>
          <input className="fld" inputMode="numeric" value={userId} onChange={(e) => setUserId(e.target.value)} placeholder="关联真实用户后才可升级即时会话" />
        </label>
        <label className="field">
          <span className="bf-legend">标题</span>
          <input className="fld" data-proof="support-ticket-create-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="例:提现审核进度咨询" />
        </label>
        <label className="field">
          <span className="bf-legend">问题描述</span>
          <textarea className="fld" data-proof="support-ticket-create-body" rows={4} value={body} onChange={(e) => setBody(e.target.value)} placeholder="写清用户诉求、截图/订单号/交易号等关键信息" style={{ resize: "vertical" }} />
        </label>
      </div>
    </Modal>
  );
}

"use client";

/**
 * L1 · KPI 看板 — 8 KPI 卡矩阵 + 单 KPI 下钻 + 趋势/阈值叠加 + 口径锁定表。
 * 数值/目标/spark 全部 join 自 KPIS(B 域同口径单一源);口径与目标只读锁定,页面无修改入口。
 * 视图参数(时间窗/粒度/Phase 叠加/黄灯偏移)实时生效;聚合 CSV 无 PII,免确认并落审计。
 */
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { AutoGloss } from "@/app/components/kit/gloss";
import { TabGroup } from "@/app/components/kit/tab-group";
import { displayAdminError } from "@/lib/admin/error-messages";
import { PaginationExemptionList } from "../design-kit";
import { LDataState, kpiState, num, rec, rows, strings, type KpiRow } from "./live-data";
import { readL1LiveTotals } from "./l1-l2-live-data";
import { L1LiveTotals } from "./l1-l2-live-fallback";
import { ViewParamModal, type ViewParamReq } from "./view-param-modal";
import type { LCtx } from "./types";
import { fetchL1Kpi, fetchL1KpiDrilldown, fetchL1KpiTrend, type L1KpiQuery } from "@/lib/admin/l-client";
import { validateL1Dashboard, validateL1Drilldown, validateL1Trend } from "./l1-kpi-contract";
import { resolveL1ExportMode, resolveL1ExportUnavailableReason, submitL1Export, type L1ExportSource } from "./l1-export-contract";
import { loadL1LocalView, saveL1LocalView, type L1Window } from "./l1-local-view";
import { createL1ReadController } from "./l1-request-generation";
import { assertL1AttributionLinks } from "./l-attribution-routes";

type Kpi = KpiRow & {
  available?: boolean;
  unavailableReason?: string;
  status?: string;
  momDelta?: number | null;
  numerator?: number;
  denominator?: number;
};
type KpiExt = {
  fx: string;
  fxBold: string[];
  num: string;
  den: string;
  delta: string;
  note: string;
  jump: { label: string; href?: string }[];
};
const LED_COLOR = { g: "var(--success)", y: "var(--warning)", r: "var(--danger)" } as const;

function sparkPath(series: readonly number[], w: number, h: number): string {
  if (series.length < 2) return "";
  const min = Math.min(...series), max = Math.max(...series), rng = max - min || 1;
  return series.map((v, i) => `${i ? "L" : "M"}${((i / (series.length - 1)) * w).toFixed(1)} ${(h - 3 - ((v - min) / rng) * (h - 6)).toFixed(1)}`).join(" ");
}
const tgtLabel = (k: Kpi) => {
  const [low = 0, high = 0] = k.band ?? [];
  return k.dir === "band" ? `健康带 ${low}–${high}${k.unit}` : `目标 ${k.dir === "lte" ? "< " : "> "}${k.target}${k.unit}`;
};
const tgtValue = (k: Kpi) => (k.dir === "band" ? (k.band?.[0] ?? k.target) : k.target);

export function L1HeaderActions({ ctx, source }: { ctx: LCtx; source?: L1ExportSource | null }) {
  const sourceUnavailable = Boolean(ctx.biError || ctx.biLoading || (source && source.status !== "ready"));
  const exportData = source ? source.data : ctx.biData?.l1;
  const exportMode = resolveL1ExportMode(exportData, sourceUnavailable);
  const exportable = exportMode !== null;
  const exportUnavailableReason = resolveL1ExportUnavailableReason(
    exportData, ctx.biLoading || source?.status === "loading" ? "loading" : ctx.biError || source?.status === "error" ? "error" : "ready",
  );
  const complete = exportMode === "series";
  const exportKpi = async () => {
    if (!ctx.canExport) return;
    try {
      const submittedMode = await submitL1Export(
        exportData,
        sourceUnavailable,
        ctx.biActions?.createReport,
        source?.query ?? { window: "7d" },
      );
      if (!submittedMode) {
        ctx.toast("L1 权威数据当前不可导出 · 请重新读取后再试");
        return;
      }
      await ctx.reloadBi?.();
      ctx.toast(submittedMode === "series" ? "KPI 序列已导出 · 已记审计" : "KPI 当前汇总已导出 · 已记审计");
    } catch (error) {
      ctx.toast(error instanceof Error ? `导出任务提交失败 · ${displayAdminError(error)}` : "导出任务提交失败 · 请稍后重试");
    }
  };
  return (
    <>
      <span className="f-ro"><span className="d" />只读报表域 · 不改任何业务规则</span>
      {!ctx.canExport && <span className="f-ro">当前角色仅可查看 · 导出需报表管理权限</span>}
      <button className="f-cta" onClick={exportKpi} disabled={!ctx.canExport || !exportable || ctx.biLoading} title={!ctx.canExport ? "当前角色没有报表导出权限" : exportUnavailableReason}>
        {complete ? "导出 KPI 序列 CSV" : "导出 KPI 当前汇总 CSV"}
      </button>
    </>
  );
}

/** fx 公式渲染:fxBold 词高亮(cyan b),其余纯文本。 */
function renderFx(fx: string, bold: string[]) {
  if (!bold.length) return fx;
  const re = new RegExp(`(${bold.map((b) => b.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})`, "g");
  return fx.split(re).map((part, i) => (bold.includes(part) ? <b key={i}>{part}</b> : <span key={i}>{part}</span>));
}

export function L1Kpi({ ctx, onExportSource }: { ctx: LCtx; onExportSource?: (source: L1ExportSource) => void }) {
  const [selKpi, setSelKpi] = useState(1); // index → #2(最弱预警项)
  const [ylOffset, setYlOffset] = useState(10);
  const [phaseOn, setPhaseOn] = useState(true);
  const [ovlSel, setOvlSel] = useState<number[]>([1, 2, 3]);
  const [vp, setVp] = useState<ViewParamReq | null>(null);
  const [win, setWin] = useState<L1Window>("7d");
  const [customOpen, setCustomOpen] = useState(false);
  const [customFrom, setCustomFrom] = useState("");
  const [customTo, setCustomTo] = useState("");
  const [gran, setGran] = useState("week");
  const [cohortFilter, setCohortFilter] = useState("");
  const [phaseFilter, setPhaseFilter] = useState("");
  const [localeFilter, setLocaleFilter] = useState("");
  const [refFilter, setRefFilter] = useState("");
  const [localData, setLocalData] = useState<Record<string, unknown> | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [refreshError, setRefreshError] = useState("");
  const [drillKpi, setDrillKpi] = useState<Kpi | null>(null);
  const [drillTrend, setDrillTrend] = useState<number[] | null>(null);
  const [drillError, setDrillError] = useState("");
  const l1Requests = useRef(createL1ReadController());
  const selectedQuery = useRef<L1KpiQuery>({ window: "7d" });

  useEffect(() => {
    l1Requests.current.invalidate();
    setDrillKpi(null);
    setDrillTrend(null);
    setDrillError("");
    setRefreshError("");
    const parentData = ctx.biData?.l1;
    const query = selectedQuery.current;
    const hasSelection = query.window !== "7d" || Boolean(query.from || query.to || query.cohort || query.phase || query.locale || query.ref);
    if (!hasSelection) setLocalData(null);
    if (parentData && hasSelection) {
      setRefreshing(true);
      onExportSource?.({ parentData, data: parentData, query, status: "loading" });
      l1Requests.current.run(
        () => fetchL1Kpi(query),
        next => {
          validateL1Dashboard(next);
          setLocalData(next);
          setWin(query.window ?? "7d");
          onExportSource?.({ parentData, data: next, query, status: "ready" });
        },
        error => {
          setRefreshError(displayAdminError(error));
          onExportSource?.({ parentData, data: parentData, query, status: "error" });
        },
        () => setRefreshing(false),
      );
    } else {
      setRefreshing(false);
      onExportSource?.({ parentData, data: parentData, query, status: parentData ? "ready" : "loading" });
    }
  }, [ctx.biData?.l1]);

  useEffect(() => () => l1Requests.current.invalidate(), []);

  useEffect(() => {
    let saved: ReturnType<typeof loadL1LocalView>;
    try {
      saved = loadL1LocalView(window.localStorage);
    } catch {
      return;
    }
    if (!saved) return;
    setWin(saved.window);
    setCustomFrom(saved.customFrom);
    setCustomTo(saved.customTo);
    setGran(saved.gran);
    setPhaseOn(saved.phaseOn);
    setYlOffset(saved.ylOffset);
    setOvlSel(saved.ovlSel);
    setCohortFilter(saved.cohortFilter);
    setPhaseFilter(saved.phaseFilter);
    setLocaleFilter(saved.localeFilter);
    setRefFilter(saved.refFilter);
    const savedQuery: L1KpiQuery = {
        ...(saved.window === "custom" ? { window: "custom", from: saved.customFrom, to: saved.customTo } : { window: saved.window }),
        cohort: saved.cohortFilter || undefined, phase: saved.phaseFilter || undefined,
        locale: saved.localeFilter || undefined, ref: saved.refFilter || undefined,
    };
    selectedQuery.current = savedQuery;
    setRefreshing(true);
    onExportSource?.({ parentData: ctx.biData?.l1, data: ctx.biData?.l1, query: savedQuery, status: "loading" });
    l1Requests.current.run(
      () => fetchL1Kpi(savedQuery),
      (next) => {
        validateL1Dashboard(next);
        setLocalData(next);
        setRefreshError("");
        onExportSource?.({ parentData: ctx.biData?.l1, data: next, query: savedQuery, status: "ready" });
      },
      (error) => {
        setRefreshError(displayAdminError(error));
        onExportSource?.({ parentData: ctx.biData?.l1, data: ctx.biData?.l1, query: savedQuery, status: "error" });
      },
      () => setRefreshing(false),
    );
    return () => l1Requests.current.invalidate();
  }, []);

  const query = selectedQuery.current;
  const selectedReadRequired = query.window !== "7d" || Boolean(query.from || query.to || query.cohort || query.phase || query.locale || query.ref);
  const data = localData ?? (selectedReadRequired ? undefined : ctx.biData?.l1);
  const rawKpis = rows<Kpi>(data?.kpis);
  const liveTotals = readL1LiveTotals(data);
  let protocolError = "";
  if (rawKpis.length) {
    try {
      validateL1Dashboard(data);
    } catch (error) {
      protocolError = displayAdminError(error);
    }
  }
  if (!rawKpis.length && liveTotals.length) return <L1LiveTotals metrics={liveTotals} />;
  if (!rawKpis.length) return <LDataState ctx={{ ...ctx, biLoading: refreshing || ctx.biLoading, biError: refreshError || ctx.biError }} label="L1" />;
  if (protocolError) {
    return (
      <section className="l-card">
        <div className="l-b">
          <div className="ltint warn" data-module-health-state="error" style={{ fontSize: 12 }}>
            <b>L1 权威响应协议校验失败</b> · 已停止渲染可疑 KPI，未把缺项或畸形值当成经营事实。
            {ctx.reloadBi && <button className="l-btn sm" style={{ marginLeft: 10 }} onClick={() => void ctx.reloadBi?.()}>重新读取</button>}
            <span className="lcode" style={{ marginLeft: 8 }}>{protocolError}</span>
          </div>
        </div>
      </section>
    );
  }
  const KPIS = rawKpis;
  const WEEKS = strings(data?.weeks);
  const PHASE_SWITCH_IDX = num(data?.phaseSwitchIndex, -1);
  const KPI_COLORS = strings(data?.kpiColors);
  const KPI_PLAIN = rec<string>(data?.kpiPlain);
  const KPI_EXT = rec<KpiExt>(data?.kpiExt);
  const safeSelKpi = Math.min(selKpi, KPIS.length - 1);
  const states = KPIS.map((item) => item.available === false || item.value == null ? "na" : kpiState(item, ylOffset));
  const green = states.filter((s) => s === "g").length;
  const yellow = states.filter((s) => s === "y").length;
  const red = states.filter((s) => s === "r").length;
  const unavailable = states.filter((s) => s === "na").length;
  const attention = red + unavailable;
  const redNames = KPIS.filter((_, i) => states[i] === "r").map((k) => `#${k.n}`).join(" ");
  const baseKpi = KPIS[safeSelKpi];
  const k = drillKpi?.n === baseKpi.n
    ? { ...baseKpi, ...drillKpi, spark: drillTrend ?? drillKpi.spark ?? baseKpi.spark }
    : baseKpi;
  const baseExt = KPI_EXT[String(k.n)] ?? { fx: k.name, fxBold: [], num: "—", den: "—", delta: "0", note: "暂未返回该 KPI 解释", jump: [] };
  const ext = {
    ...baseExt,
    num: k.numerator == null ? baseExt.num : String(k.numerator),
    den: k.denominator == null ? baseExt.den : String(k.denominator),
  };
  const phase = rec(data?.currentPhase);
  const phaseKnown = typeof phase.code === "string" && phase.code.length > 0;
  const rs = { currentPhase: phaseKnown ? String(phase.code) : "未返回", currentMonth: phaseKnown ? num(phase.month, 0) : "—" };

  const activeQuery = (
    nextWindow: L1Window = win,
    filters: Partial<L1KpiQuery> = {},
  ): L1KpiQuery => ({
    ...(nextWindow === "custom"
      ? { window: "custom", from: customFrom, to: customTo }
      : { window: nextWindow }),
    cohort: cohortFilter || undefined,
    phase: phaseFilter || undefined,
    locale: localeFilter || undefined,
    ref: refFilter || undefined,
    ...filters,
  });

  const reloadKpi = (
    nextWindow: L1Window = win,
    filters: Partial<L1KpiQuery> = {},
  ) => {
    setRefreshing(true);
    setLocalData(data ?? null);
    const query = activeQuery(nextWindow, filters);
    selectedQuery.current = query;
    onExportSource?.({ parentData: ctx.biData?.l1, data, query, status: "loading" });
    l1Requests.current.run(
      () => fetchL1Kpi(query),
      (next) => {
        validateL1Dashboard(next);
        setLocalData(next);
        onExportSource?.({ parentData: ctx.biData?.l1, data: next, query, status: "ready" });
        setDrillKpi(null);
        setDrillTrend(null);
        setDrillError("");
        setRefreshError("");
        setWin(nextWindow);
        setCustomOpen(false);
        ctx.toast(`KPI 已按${nextWindow === "custom" ? `${customFrom} 至 ${customTo}` : nextWindow === "30d" ? "滚动 30 天" : nextWindow === "1d" ? "当日" : "滚动 7 天"}重新读取`);
      },
      (error) => {
        const message = displayAdminError(error);
        setRefreshError(message);
        onExportSource?.({ parentData: ctx.biData?.l1, data, query, status: "error" });
        ctx.toast(`KPI 刷新失败 · ${message}`);
      },
      () => setRefreshing(false),
    );
  };
  const attributionLinks = assertL1AttributionLinks(ext.jump);

  const selectKpi = async (index: number) => {
    setSelKpi(index);
    const kpiId = KPIS[index]?.n;
    if (!kpiId) return;
    setDrillKpi(null);
    setDrillTrend(null);
    setDrillError("");
    const query = activeQuery();
    try {
      const [drilldown, trend] = await Promise.all([
        fetchL1KpiDrilldown(kpiId, query),
        fetchL1KpiTrend(kpiId, query),
      ]);
      const checkedDrilldown = validateL1Drilldown(drilldown, kpiId);
      const checkedTrend = validateL1Trend(trend, kpiId);
      setDrillKpi(checkedDrilldown.selected as Kpi);
      setDrillTrend(checkedTrend.values as number[]);
    } catch (error) {
      const message = displayAdminError(error);
      setDrillError(message);
      ctx.toast(`KPI 下钻读取失败 · ${message}`);
    }
  };

  const toggleOvl = (i: number) => setOvlSel((p) => (p.includes(i) ? (p.length > 1 ? p.filter((x) => x !== i) : p) : [...p, i]));

  /* ---- 下钻图(cohort 周序列 + 目标线 + 黄线 + Phase 标记;固定 viewBox 等比缩放) ---- */
  const drillChart = () => {
    const W = 860, H = 260, P = 36;
    const s = [...k.spark];
    if (s.length < 2) return <div className="empty">当前筛选范围没有可绘制的趋势点；不会用 0 补齐缺失周。</div>;
    const tgt = tgtValue(k);
    const yl = k.dir === "lte" ? k.target * (1 + ylOffset / 100) : tgt * (1 - ylOffset / 100);
    const all = [...s, tgt, yl];
    const min = Math.min(...all) * 0.97, max = Math.max(...all) * 1.03, rng = max - min || 1;
    const X = (i: number) => P + (i / (s.length - 1)) * (W - 2 * P);
    const Y = (v: number) => H - 26 - ((v - min) / rng) * (H - 56);
    const path = s.map((v, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join(" ");
    return (
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`KPI #${k.n} cohort 周序列趋势`}>
        {s.map((_, i) => (
          <g key={i}>
            <line x1={X(i)} y1={18} x2={X(i)} y2={H - 26} stroke="var(--border)" strokeWidth={1} />
            <text x={X(i)} y={H - 8} fontSize={11} fill="var(--ink-4)" textAnchor="middle">{WEEKS[i]}</text>
          </g>
        ))}
        {phaseOn && PHASE_SWITCH_IDX >= 0 && (
          <g>
            <rect x={X(PHASE_SWITCH_IDX) - 1} y={18} width={2} height={H - 44} fill="var(--cyan)" opacity={0.45} />
            <text x={X(PHASE_SWITCH_IDX) + 5} y={30} fontSize={11} fill="var(--cyan)">Phase 切换</text>
          </g>
        )}
        <line x1={P} y1={Y(tgt)} x2={W - P} y2={Y(tgt)} stroke="var(--success)" strokeWidth={1.4} strokeDasharray="5 4" />
        <text x={W - P} y={Y(tgt) - 5} fontSize={11} fill="var(--success)" textAnchor="end">目标 {tgt}{k.unit}</text>
        <line x1={P} y1={Y(yl)} x2={W - P} y2={Y(yl)} stroke="var(--warning)" strokeWidth={1.2} strokeDasharray="3 4" />
        <text x={W - P} y={Y(yl) + 13} fontSize={11} fill="var(--warning)" textAnchor="end">黄灯 {yl.toFixed(1)}{k.unit}</text>
        <path d={`${path} L${X(s.length - 1)} ${H - 26} L${X(0)} ${H - 26} Z`} fill="var(--cyan)" opacity={0.07} />
        <path d={path} fill="none" stroke="var(--cyan)" strokeWidth={2.2} />
        {s.map((v, i) => (
          <g key={i}>
            <circle cx={X(i)} cy={Y(v)} r={3.4} fill="#0A0A0A" stroke="var(--cyan)" strokeWidth={2} />
            <text x={X(i)} y={Y(v) - 9} fontSize={11} fill="var(--ink-3)" textAnchor="middle">{v}</text>
          </g>
        ))}
      </svg>
    );
  };

  /* ---- 趋势叠加(指数化:实际 ÷ 目标 → 达标线 100) ---- */
  const ovlChart = () => {
    const drawable = ovlSel.filter((index) => KPIS[index]?.available !== false && (KPIS[index]?.spark?.length ?? 0) >= 2);
    if (!drawable.length) return <div className="empty">当前所选 KPI 没有完整趋势点，暂不绘制叠加线。</div>;
    const W = 1240, H = 230, P = 40, min = 80, max = 125;
    const X = (i: number) => P + (i / (WEEKS.length - 1)) * (W - 2 * P);
    const y100 = H - 24 - ((100 - min) / (max - min)) * (H - 44);
    return (
      <svg className="ovl-chart" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="多 KPI 指数化叠加趋势">
        {WEEKS.map((w, i) => (
          <g key={w}>
            <line x1={X(i)} y1={14} x2={X(i)} y2={H - 24} stroke="var(--border)" />
            <text x={X(i)} y={H - 6} fontSize={11} fill="var(--ink-4)" textAnchor="middle">{w}</text>
          </g>
        ))}
        {phaseOn && PHASE_SWITCH_IDX >= 0 && (
          <g>
            <rect x={X(PHASE_SWITCH_IDX) - 1} y={14} width={2} height={H - 38} fill="var(--cyan)" opacity={0.45} />
            <text x={X(PHASE_SWITCH_IDX) + 5} y={26} fontSize={11} fill="var(--cyan)">Phase 切换</text>
          </g>
        )}
        {drawable.map((i) => {
          const kk = KPIS[i];
          const tgt = tgtValue(kk);
          const idx = kk.spark.map((v) => (kk.dir === "lte" ? (tgt / v) * 100 : (v / tgt) * 100));
          const path = idx.map((v, j) => {
            const y = H - 24 - ((Math.min(Math.max(v, min), max) - min) / (max - min)) * (H - 44);
            return `${j ? "L" : "M"}${X(j).toFixed(1)} ${y.toFixed(1)}`;
          }).join(" ");
          return <path key={i} d={path} fill="none" stroke={KPI_COLORS[i]} strokeWidth={2} />;
        })}
        <line x1={P} y1={y100} x2={W - P} y2={y100} stroke="var(--success)" strokeWidth={1.4} strokeDasharray="5 4" />
        <text x={W - P} y={y100 - 5} fontSize={11} fill="var(--success)" textAnchor="end">达标线 = 各自目标值(指数 100)</text>
      </svg>
    );
  };

  return (
    <div>
      {refreshError && (
        <div className="ltint warn" data-module-health-state="error" style={{ fontSize: 12, marginBottom: 10 }}>
          <b>KPI 刷新未成功</b> · 当前仍显示上一次已校验快照，时间窗未切换。{refreshError}
        </div>
      )}
      {/* stat strip */}
      <div className="f-stats">
        <div className="f-stat ok"><div className="k">达标 KPI</div><div className="v">{green} / {KPIS.length}</div><div className="sub">绿灯 · 高于目标线</div></div>
        <div className="f-stat warn"><div className="k">预警 KPI</div><div className="v">{yellow}</div><div className="sub">黄灯 · 距目标 −{ylOffset}% 区间内</div></div>
        <div className="f-stat danger"><div className="k">未达 + 不可计算</div><div className="v">{attention} / {KPIS.length}</div><div className="sub">未达 {red} 项{redNames ? ` (${redNames})` : ""} · 不可计算 {unavailable} 项 · 缺分母不判 0%</div></div>
        <div className="f-stat cyan"><div className="k">当前 Phase</div><div className="v">{rs.currentPhase}{phaseKnown ? ` · 月 ${rs.currentMonth}` : ""}</div><div className="sub">{PHASE_SWITCH_IDX >= 0 ? "趋势图已叠加事件 Phase 切换标记" : "当前窗口未识别到 Phase 切换"}</div></div>
      </div>

      {/* view params bar(全部仅视图 · 实时生效 · 普通确认批) */}
      <div className="view-bar">
        <TabGroup<L1Window>
          className="chips"
          label="时间窗"
          labelClassName="lb"
          value={win}
          items={["1d", "7d", "30d", "custom"] as const}
          onSelect={(v) => {
            if (v === "custom") {
              setCustomOpen(true);
              return;
            }
            void reloadKpi(v);
          }}
          itemClassName={(_v, selected) => `chip${selected ? " sel" : ""}`}
        >{(v) => ({ "1d": "当日", "7d": "滚动 7d", "30d": "滚动 30d", custom: "自定义" })[v]}</TabGroup>
        {customOpen && (
          <div className="chips">
            <label className="lb" htmlFor="l1-custom-from">起</label>
            <input id="l1-custom-from" type="date" value={customFrom} onChange={(event) => setCustomFrom(event.target.value)} />
            <label className="lb" htmlFor="l1-custom-to">止</label>
            <input id="l1-custom-to" type="date" value={customTo} onChange={(event) => setCustomTo(event.target.value)} />
            <button className="l-btn sm" disabled={!customFrom || !customTo || customFrom > customTo || refreshing} onClick={() => void reloadKpi("custom")}>应用自定义</button>
          </div>
        )}
        <div className="sep" />
        <TabGroup
          className="chips"
          label="cohort 粒度"
          labelClassName="lb"
          value={gran}
          items={["week", "month"] as const}
          onSelect={(v) => { setGran(v); ctx.toast(`视图已切换:${v === "week" ? "注册周 YYYY-Www" : "注册月"} · 仅视图参数,实时生效`); }}
          itemClassName={(_v, selected) => `chip${selected ? " sel" : ""}`}
        >{(v) => (v === "week" ? "注册周 YYYY-Www" : "注册月")}</TabGroup>
        <div className="sep" />
        <button className={"toggle" + (phaseOn ? " on" : "")} onClick={() => { setPhaseOn(!phaseOn); ctx.toast(`Phase 效果叠加:${!phaseOn ? "开启" : "关闭"}`); }}>
          <span className="tk" />Phase 效果叠加
        </button>
        <div className="sep" />
        <div className="chips"><span className="lb">黄灯预警偏移</span>
          <span className="lcode">目标 −{ylOffset}%</span>
          <button className="l-btn sm" onClick={() => setVp({
            title: "黄灯预警偏移",
            detail: "状态灯黄线 = 目标值 − N%。落在「目标 − N%」与目标之间的 KPI 标黄灯(预警),低于黄线标红灯(未达)。只影响看板状态灯与图上黄线位置。",
            current: ylOffset, unit: "%", min: 5, max: 20,
            onApply: (n) => { setYlOffset(n); ctx.toast(`黄灯预警偏移 → 目标 −${n}% · 仅视图参数`); },
          })}>调整</button>
        </div>
        <button className="l-btn sm" onClick={() => void reloadKpi()} disabled={refreshing}>{refreshing ? "刷新中…" : "刷新 KPI"}</button>
        <button className="l-btn sm" style={{ marginLeft: "auto" }} onClick={() => {
          let saved: ReturnType<typeof saveL1LocalView> = null;
          try {
            saved = saveL1LocalView(window.localStorage, { window: win, customFrom, customTo, gran, phaseOn, ylOffset, ovlSel, cohortFilter, phaseFilter, localeFilter, refFilter });
          } catch {
            saved = null;
          }
          ctx.toast(saved ? "视图已保存到本机浏览器；刷新后会按已保存参数重新读取权威数据" : "视图参数无效或本机存储不可用，未保存");
        }}>保存为视图</button>
        <span className="lcode lock" title="口径与目标值只读；仅保存本机浏览器视图参数，不保存数据、权限或业务状态">视图参数 · 本机浏览器保存 · 实时生效 · 不落确认</span>
      </div>

      {/* (a) 8-KPI matrix */}
      <div className="kpi-grid">
        {KPIS.map((kk, i) => {
          const st = states[i];
          const ex = KPI_EXT[kk.n];
          const dUp = !ex.delta.startsWith("-");
          const goodUp = kk.dir !== "lte";
          return (
            <button key={kk.n} className={"kpi-card" + (i === selKpi ? " sel" : "")} aria-pressed={i === selKpi} onClick={() => selectKpi(i)} title="点击下钻">
              <div className="top"><span className="n">#{kk.n}</span><span className="nm"><AutoGloss>{kk.name}</AutoGloss></span><span className={"led " + st} /></div>
              <div className="vrow">
                <span className="v">{kk.available === false || kk.value == null ? "不可计算" : kk.value}<span className="u">{kk.available === false || kk.value == null ? "" : kk.unit}</span></span>
                <span className="tgt">{tgtLabel(kk)}</span>
                <span className={"delta " + (dUp === goodUp ? "up" : "dn")}>{ex.delta === "—" ? "环比 —" : `${dUp ? "▲" : "▼"} ${ex.delta.replace("-", "")}`}</span>
              </div>
              {kk.spark.length === 0 ? (
                <span className="spark-empty" data-proof="l1-kpi-trend-unavailable">趋势数据不足</span>
              ) : (
                <svg className="spark" viewBox="0 0 150 30" preserveAspectRatio="none" aria-hidden>
                  <path d={sparkPath(kk.spark, 150, 30)} fill="none" stroke={st === "na" ? "var(--ink-4)" : LED_COLOR[st]} strokeWidth={1.8} />
                </svg>
              )}
              <div className="ft"><span className="ev" title={ex.fx}><AutoGloss>{KPI_PLAIN[kk.n]}</AutoGloss></span><span className="ph">{rs.currentPhase}</span><span className="lat">~2min</span></div>
            </button>
          );
        })}
      </div>

      {/* (b) 单 KPI 下钻 */}
      <section className="l-card">
        <div className="l-h">
          <span className="ttl">单 KPI 下钻 · #{k.n} {k.name}</span>
          <span className="sub">· 口径公式 / 分子分母 / 切片 / 趋势</span>
          <div className="r">
            <div className="chips"><span className="lb">真实切片</span>
              <input aria-label="cohort 筛选" placeholder="YYYY-Www" value={cohortFilter} onChange={(event) => setCohortFilter(event.target.value)} />
              <select aria-label="Phase 筛选" value={phaseFilter} onChange={(event) => setPhaseFilter(event.target.value)}>
                <option value="">全部 Phase</option>
                {["P1", "P2", "P3", "P4", "P5", "P6"].map((value) => <option key={value} value={value}>{value}</option>)}
              </select>
              <input aria-label="locale 筛选" placeholder="locale" value={localeFilter} onChange={(event) => setLocaleFilter(event.target.value)} />
              <input aria-label="渠道筛选" placeholder="ref" value={refFilter} onChange={(event) => setRefFilter(event.target.value)} />
              <button className="l-btn sm" disabled={refreshing} onClick={() => void reloadKpi()}>应用切片</button>
              <button className="l-btn sm" disabled={refreshing} onClick={() => {
                setCohortFilter("");
                setPhaseFilter("");
                setLocaleFilter("");
                setRefFilter("");
                void reloadKpi(win, { cohort: "", phase: "", locale: "", ref: "" });
              }}>清除切片</button>
            </div>
          </div>
        </div>
        <div className="drill">
          <div className="meta">
            <div className="formula">
              <div className="lb" title="指标口径已锁定"><AutoGloss>这项指标怎么算 · 统计规则统一管理,这里只能看不能改</AutoGloss></div>
              <div className="plain"><AutoGloss>{KPI_PLAIN[k.n]}</AutoGloss></div>
              <div className="fx">{renderFx(ext.fx, ext.fxBold)}</div>
              <div className="anchor">口径编号 #{k.n} · 数据批次 {k.vis}</div>
            </div>
            <div className="nd">
              <div className="it"><div className="k">分子(实时)</div><div className="v" style={{ color: "var(--cyan)" }}>{ext.num}</div></div>
              <div className="it"><div className="k">分母(实时)</div><div className="v">{ext.den}</div></div>
              <div className="it"><div className="k">当前值</div><div className="v" style={{ color: k.available === false || k.value == null ? "var(--ink-4)" : "var(--success)" }}>{k.available === false || k.value == null ? "不可计算" : `${k.value}${k.unit}`}</div></div>
              <div className="it"><div className="k">目标值</div><div className="v" style={{ color: "var(--ink-3)" }}>{tgtLabel(k).replace("目标 ", "").replace("健康带 ", "")}</div></div>
            </div>
            <div className="ltint" style={{ fontSize: 12 }}><b>解读</b> · <AutoGloss>{ext.note}</AutoGloss></div>
            <div className="jump">
              {attributionLinks.map((j) => (
                <Link key={j.label} className="l-btn sm" href={j.href}>{j.label} →</Link>
              ))}
            </div>
          </div>
          <div className="chart-pane">
            {drillError && (
              <div className="ltint warn" style={{ fontSize: 12, marginBottom: 10 }}>
                <b>下钻/趋势权威响应不可用</b> · 已保留概览卡，不使用异常响应覆盖明细。{drillError}
              </div>
            )}
            {drillChart()}
            <div className="legend">
              <span className="it"><span className="lsw" style={{ background: "var(--cyan)" }} />cohort 周序列</span>
              <span className="it" style={{ color: "var(--success)" }}><span className="lsw dash" />目标线</span>
              <span className="it" style={{ color: "var(--warning)" }}><span className="lsw dash" />黄灯预警线(目标 −{ylOffset}%)</span>
              <span className="it" style={{ color: "var(--ink-4)" }}><span className="lsw" style={{ width: 8, height: 10 }} />事件 Phase 切换标记</span>
            </div>
          </div>
        </div>
      </section>

      {/* (c) 趋势 & 阈值叠加 */}
      <section className="l-card">
        <div className="l-h">
          <span className="ttl">趋势 &amp; 阈值视图</span>
          <span className="sub">· <AutoGloss>多 KPI cohort 周序列叠加 · 观察 Phase 切换对 KPI 的影响 · 归因跳 B4 / H1</AutoGloss></span>
          <div className="r"><span className="lcode electric" title="按每条业务事件携带的阶段标记聚合">按事件自带的 Phase 标记聚合</span></div>
        </div>
        <div className="l-b">
          <div className="ovl-picks">
            {KPIS.map((kk, i) => {
              const on = ovlSel.includes(i);
              return <button key={kk.n} className={"chip" + (on ? " sel" : "")} aria-pressed={on} style={on ? { background: KPI_COLORS[i], color: "#0A0A0A" } : undefined} onClick={() => toggleOvl(i)}>#{kk.n} {kk.name}</button>;
            })}
          </div>
          {ovlChart()}
          <div className="legend">
            {ovlSel.map((i) => <span key={i} className="it"><span className="lsw" style={{ background: KPI_COLORS[i] }} />#{KPIS[i].n} {KPIS[i].name}</span>)}
            <span className="it" style={{ color: "var(--ink-4)" }}>纵轴 = 实际值 ÷ 目标值(达标线 100)</span>
          </div>
        </div>
      </section>

      {/* 口径锁定表 */}
      <section className="l-card">
        <div className="l-h">
          <span className="ttl">KPI 口径锁定表</span>
          <span className="sub">· <AutoGloss>每项 KPI 怎么算一目了然 · 要改算法须走事件中台治理 + 操作确认,本页改不了</AutoGloss></span>
          <div className="r"><span className="lcode lock" title="指标口径已锁定">🔒 算法锁定</span><span className="lcode lock" title="经营目标已锁定">🔒 目标锁定</span></div>
        </div>
        <div style={{ overflowX: "auto" }}>
          <table className="l-tbl" style={{ minWidth: 900 }}>
            <thead><tr><th>#</th><th>KPI</th><th>怎么算(服务端口径 · 只读)</th><th className="num">目标</th><th>落地批次</th><th>状态</th></tr></thead>
            <tbody>
              {KPIS.map((kk, i) => {
                const st = states[i];
                return (
                  <tr key={kk.n}>
                    <td className="mono">{kk.n}</td>
                    <td style={{ fontWeight: 600, color: "var(--ink)" }}><AutoGloss>{kk.name}</AutoGloss></td>
                    <td><div style={{ color: "var(--ink-2)" }}><AutoGloss>{KPI_PLAIN[kk.n]}</AutoGloss></div><div className="mono fx" style={{ color: "var(--ink-4)", fontSize: 11.5, marginTop: 3 }}>{renderFx(KPI_EXT[kk.n].fx, KPI_EXT[kk.n].fxBold)}</div></td>
                    <td className="num mono" style={{ color: "var(--ink)" }}>{tgtLabel(kk).replace("目标 ", "").replace("健康带 ", "")}</td>
                    <td><span className="lcode">{kk.vis}</span></td>
                    <td>{st === "g" ? <span className="bdg ok">达标</span> : st === "y" ? <span className="bdg warn">预警</span> : st === "na" ? <span className="bdg">不可计算</span> : <span className="bdg bad">未达</span>}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div className="l-b" style={{ paddingTop: 12 }}>
          <div className="ltint" style={{ fontSize: 12 }}><b>三点说明</b> · <AutoGloss>① #5 是推广率不是收入:算的是发出过邀请的设备持有者占比(不是收入指标);② #6 Nova:推送事件早已登记,数据一直是全的;③ #7 刚补齐:依赖团队分销关系树,早期只有粗略计数,本看板(V4)起完整下钻。</AutoGloss></div>
        </div>
      </section>

      <p className="f-foot"><b>L1 没有任何「写数据」动作</b>:<AutoGloss>KPI 怎么算由事件统计规则统一治理,这里只配置呈现、下钻查询与聚合导出。导出内容为 8 项 KPI 的聚合序列,</AutoGloss><b>不含任何用户隐私明文</b>,<AutoGloss>每次导出都会生成可追溯记录。异常 KPI 的归因下钻:转化类(#1–#4)跳 L2 漏斗,财务类(#8 / 提现兑付)跳 L3 报表,团队类(#5/#7)跳 L4 网络报表。</AutoGloss></p>
      <PaginationExemptionList
        items={[
          {
            label: "KPI 口径锁定表",
            kind: "reference-catalog",
            maxRows: 8,
            reason: "八项 KPI 为固定验收口径,需要同屏锁定算式和状态",
          },
        ]}
      />

      {vp && <ViewParamModal req={vp} onClose={() => setVp(null)} />}
    </div>
  );
}
